{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The bucket has no account-level bucket controls preventing public ACLs or policies, allowing a future configuration change to expose its contents publicly."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket lacks explicit KMS encryption",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly enforce SSE-KMS for newly stored objects, reducing control and auditability over encryption key usage."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "Without versioning, overwritten or deleted objects cannot be recovered from prior versions, increasing the impact of accidental deletion or compromise."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle controls; incomplete multipart uploads can remain indefinitely and consume storage without representing recoverable objects."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destruction of a non-empty S3 bucket is enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The force_destroy setting permits Terraform to delete all objects and object versions when destroying the bucket, increasing the risk of irreversible bulk data loss."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "changeme_aws_s3_bucket_backend_simple" {
  force_destroy = false
  bucket        = "changeme-${random_id.changeme_backends_s3_bucket_name.hex}"
}

resource "aws_s3_bucket_public_access_block" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = "alias/aws/s3"
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}
",
  "fix_summary": "Disabled forced deletion, blocked all forms of public access, enabled SSE-KMS using the AWS-managed S3 key, and enabled object versioning. Added a non-destructive lifecycle rule that removes incomplete multipart uploads after seven days."
}
